from __future__ import annotations
from math import sqrt
from typing import TypeAlias
Pair: TypeAlias = tuple[complex, complex]

def normalize(p: Pair) -> Pair:
    n = sqrt(abs(p[0])**2 + abs(p[1])**2)
    if n == 0: raise ValueError("nonzero input required")
    return p[0]/n, p[1]/n

def act(u: complex, p: Pair) -> Pair: return u*p[0], u*p[1]
def recover(a: Pair, b: Pair) -> complex:
    return a[0].conjugate()*b[0] + a[1].conjugate()*b[1]
def distance(a: Pair, b: Pair) -> float:
    return sqrt(abs(a[0]-b[0])**2 + abs(a[1]-b[1])**2)

a = normalize((2-1j, 1+3j)); chosen = complex(3/5,4/5); b = act(chosen,a)
found = recover(a,b)
print("chosen", chosen, "recovered", found, "residual", distance(b,act(found,a)))

